  "final": {
    "question": "What should happen when the same request arrives twice?",
    "is_question": true,
    "form": "An event sequence: Participants → First request → Repeat request → Verification → Observations → End state.",
    "object": "One persistent sequence made of six thin, matte event cards.",
    "object_in_pieces": true
  },
  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The story depends on Leena’s duplicate-request concern, idempotency key design, replay verifier and precisely bounded contributions."
    },
    "backdrop": {
      "result": "pass",
      "reason": "The cards explain arrival order, matching keys, contribution boundaries and benchmark proportions rather than merely decorating the page."
    },
    "depth": {
      "result": "pass",
      "reason": "The sequence progresses from a first arrival through repetition and verification to evidence and a concluding answer."
    },
    "clipart": {
      "result": "pass",
      "reason": "The event cards represent her daily working artifact rather than a stock backend-engineering emblem."
    },
    "honesty": {
      "result": "pass",
      "reason": "The plan preserves team attribution, contributor status, benchmark scope and confidentiality while explicitly separating illustration from actual implementation."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The first viewport includes her name, backend focus, concrete confirmed contributions, team scope and an email action."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The opening question is understandable without specialist knowledge, and the technical explanation remains precise and bounded."
    }
  },
